// DOMINION redesign, pass 50 ("Final Cut"): the shared chrome every redesigned Dominion page draws with. Each piece
// reproduces the markup the mockup kit (plans/evil-mode-rework/redesign-50/src) builds at pass 50, with live data in
// place of the mockup's sample numbers. Styles come from r50.css (generated by tools/dominion/port-r50.py).
//
// A page is `page({ id, g, kind, body })`: the 960x540 root (`.r50[data-g]`, the mockups' #stage) and the `.scr.nv`
// screen inside it. Build `body` from bg(), top(), pn(), foot(), tabs() and keys() plus the page's own markup.
// Buttons call `go(act, arg)`: a tap target (data-act) the scene's acts table handles.

import './r50.css';
import './game.css';
import { act, esc } from '../../../kit';
import { R5_SIZES } from './sizes';

export { esc };

/** A page's group (the mockups' 17 groups): picks the area colour, the place, the time of day, the wipe and the tabs. */
export type R5Group = 'Start' | 'Guide' | 'HQ' | 'The Day' | 'Jobs' | 'Crew' | 'Pokémon' | 'Opposition' | 'Trainers' | 'Gimmicks'
  | 'Events' | 'Empire' | 'The Chair' | 'Rotom' | 'Menu' | 'Settings' | 'Map of pages';

// ---------- small helpers (kit.js) ----------

export const r5src = (k: string): string => `assets/images/dominion/r50/${k}.png`;
export const rep = (n: number, f: (i: number) => string): string => Array.from({ length: n }, (_, i) => f(i)).join('');
export const map = <T>(a: readonly T[] | undefined, f: (x: T, i: number) => string): string => (a ?? []).map(f).join('');
/** Stagger for an entrance: --i and --d (the delay), as the mockups' st(). */
export const st = (i: number, d = 60): string => `style="--i:${i};--d:${i * d}ms"`;
/** A tap target. In the mockups this was data-go="page"; in the game it is the scene's act with an argument. */
export const go = (name: string, arg: string | number = ''): string => (name ? act(name, arg).trim() : '');

/** A sprite at scale `sc` of its own pixels (the mockups' spr()). */
export function spr(k: string, sc = 2, cls = '', style = ''): string {
  const s = R5_SIZES[k] ?? [32, 32];
  return `<img class="px ${cls}" src="${r5src(k)}" alt="" draggable="false" style="width:${Math.round(s[0] * sc)}px;height:${Math.round(s[1] * sc)}px;${style}">`;
}
/** A sprite `h` px tall (never more than 5x its pixels), the mockups' SP(). */
export const SP = (k: string, h: number, cls = ''): string => spr(k, Math.min(5, h / (R5_SIZES[k] ?? [32, 32])[1]), cls);

/** Person colours (the face ring, the name in a text box). */
export const PCOL: Record<string, string> = {
  'c-rook': '#3f7fd9', 'c-rook0': '#3f7fd9', 'c-dale': '#6f9a3a', 'c-gus': '#e0901c', 'c-gruntb': '#8a6ad9', 'c-rosa': '#25b3c7', 'c-mina': '#a25fe0', 't-natebig': '#e0294a', 'v-nate': '#e0294a', 't-redbig': '#ef3b2c', 't-giovanni': '#7d8298', 't-gio': '#7d8298',
  't-petrel': '#9a4fd0', 't-looker': '#a8885a', 't-policeman': '#3a6fd0', 't-koga': '#7a3cc9', 't-misty': '#2a8ad9', 't-erika': '#4caf50', 't-sabrina': '#d14b8f', 'p-rotom': '#ff8a1c', 't-rich': '#c9a24a', 't-applicant': '#3aa86a', 't-grunt': '#6d6d78', 't-biker': '#9a6a3a', 't-clerkm': '#4a8ab0', 'c-archer': '#4a5fa0',
};
export const pc = (k: string): string => PCOL[k] ?? '#c1121f';

/** A round portrait (the mockups' face()). */
export function face(k: string, sz = 44, colour = pc(k)): string {
  const s = R5_SIZES[k] ?? [32, 32], sc = sz * (k.startsWith('p-') ? 1.25 : 2.5) / s[1];
  return `<span class="face" data-nocheck="" style="--c:${colour};width:${sz}px;height:${sz}px"><img class="px" src="${r5src(k)}" alt="" style="width:${Math.round(s[0] * sc)}px;height:${Math.round(s[1] * sc)}px;margin-left:${-Math.round((s[0] * sc - sz) / 2)}px;margin-top:${k.startsWith('p-') ? 0 : -Math.round(sz * 0.08)}px"></span>`;
}

/** A round portrait around any picture (a team-coloured member look, a Pokémon, the run's Boss). */
export const faceOf = (inner: string, sz = 44, colour = '#c1121f', testid = ''): string =>
  `<span class="face" data-nocheck="" style="--c:${colour};width:${sz}px;height:${sz}px"${testid ? ` data-testid="${testid}"` : ''}>${inner}</span>`;

/** A sprite from the r50 folder when the mockups had it, else the game's own Dominion folder (assets/images/dominion/). */
export function art(k: string, h: number, cls = ''): string {
  if (R5_SIZES[k]) return SP(k, h, cls);
  return `<img class="px ${cls}" src="assets/images/dominion/${esc(k)}.png" alt="" draggable="false" style="height:${h}px;width:auto">`;
}

// ---------- per-group tables (passes 3, 5, 15, 27, 30, 35, 36, 46) ----------

